CREATE TABLE IF NOT EXISTS payment_intents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), business_id uuid NOT NULL REFERENCES businesses(id), sale_id uuid REFERENCES sales(id), amount_minor bigint NOT NULL CHECK (amount_minor > 0), currency char(3) NOT NULL DEFAULT 'COP', status text NOT NULL DEFAULT 'CREATED', idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz);
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_intent_id uuid NOT NULL UNIQUE REFERENCES payment_intents(id), amount_minor bigint NOT NULL CHECK (amount_minor > 0), currency char(3) NOT NULL DEFAULT 'COP', method text NOT NULL DEFAULT 'VEMTAS_BALANCE', status text NOT NULL DEFAULT 'POSTED', ledger_transaction_id uuid REFERENCES ledger_transactions(id), created_at timestamptz NOT NULL DEFAULT now());
